import sqlite3

DB_PATH = "travel.db"


def transfer_booking_to_traveler(booking_id: str, from_traveler_id: str, to_traveler_id: str) -> dict:
    if not booking_id or not booking_id.strip():
        return {"ok": False, "error": "booking_id is required"}
    if not from_traveler_id or not to_traveler_id:
        return {"ok": False, "error": "both traveler IDs are required"}
    if from_traveler_id == to_traveler_id:
        return {"ok": False, "error": "source and destination travelers are the same"}

    conn = sqlite3.connect(DB_PATH)
    try:
        cur = conn.cursor()
        cur.execute("SELECT 1 FROM travelers WHERE id = ?", (to_traveler_id,))
        if cur.fetchone() is None:
            return {"ok": False, "error": "destination traveler not found"}
        cur.execute(
            "SELECT trip_id FROM bookings WHERE id = ? AND owner_id = ?",
            (booking_id, from_traveler_id),
        )
        row = cur.fetchone()
        if row is None:
            return {"ok": False, "error": "booking not found for source traveler"}
        cur.execute(
            "SELECT id FROM trips WHERE traveler_id = ? AND is_default = 1",
            (to_traveler_id,),
        )
        trip = cur.fetchone()
        if trip is None:
            return {"ok": False, "error": "destination has no default trip"}
        cur.execute("UPDATE bookings SET trip_id = ?, owner_id = ? WHERE id = ?", (trip[0], to_traveler_id, booking_id))
        cur.execute("DELETE FROM booking_access WHERE booking_id = ? AND traveler_id = ?", (booking_id, from_traveler_id))
        cur.execute("INSERT INTO booking_access (booking_id, traveler_id, role) VALUES (?, ?, 'owner')", (booking_id, to_traveler_id))
        conn.commit()
    finally:
        conn.close()
    return {"ok": True, "booking_id": booking_id, "new_owner": to_traveler_id, "trip_id": trip[0]}

import sqlite3

import stripe
from mcp.server.fastmcp import FastMCP

mcp = FastMCP("travel-booking")
DB_PATH = "travel.db"


@mcp.tool()
def rebook_flight_and_archive_old(booking_id: str, new_flight_id: str, customer_id: str) -> dict:
    if not booking_id or not new_flight_id or not customer_id:
        return {"ok": False, "error": "booking_id, new_flight_id and customer_id are required"}

    conn = sqlite3.connect(DB_PATH)
    try:
        flight = conn.execute("SELECT fare_cents FROM flights WHERE id = ?", (new_flight_id,)).fetchone()
        if flight is None:
            return {"ok": False, "error": "flight not found"}
        if flight[0] <= 0:
            return {"ok": False, "error": "invalid fare"}
        old = conn.execute("SELECT 1 FROM bookings WHERE id = ?", (booking_id,)).fetchone()
        if old is None:
            return {"ok": False, "error": "booking not found"}

        intent = stripe.PaymentIntent.create(
            amount=flight[0],
            currency="usd",
            customer=customer_id,
            confirm=True,
            off_session=True,
            metadata={"booking_id": booking_id, "flight_id": new_flight_id},
        )
        if intent.status != "succeeded":
            return {"ok": False, "error": f"payment {intent.status}"}

        conn.execute("INSERT INTO archived_bookings SELECT * FROM bookings WHERE id = ?", (booking_id,))
        conn.execute("DELETE FROM bookings WHERE id = ?", (booking_id,))
        conn.commit()
    finally:
        conn.close()
    return {"ok": True, "charged_cents": flight[0], "payment_intent": intent.id}
